steps.cmd:
mkdir -p /app/output && cat > /app/output/gen.py <<'PY'
"""RoboWits stand_pages controller. One Robot client; logged commands replayable with --replay."""
import sys, json, pathlib, time, traceback
sys.path.insert(0, '/opt/tools')
import numpy as np
from PIL import Image
from scipy.spatial.transform import Rotation as Rot
from rcb_client import Robot, EpisodeOver
OUT=pathlib.Path('/app/output')
r=Robot()
spec=r.spec()
(OUT/'spec.json').write_text(json.dumps(spec,indent=2))
res=None
counter=0
def record(x, label='obs'):
 global res,counter
 res=x; counter+=1
 d=OUT/f'{counter:03d}_{label}'; x.save(str(d))
 (OUT/'latest.json').write_text(json.dumps(x.meta,indent=2))
 for cam,img in x.last.items(): Image.fromarray(img).save(OUT/f'{cam}.png')
 print('RESULT',counter, 'done', x.meta.get('done'), 'reason', x.meta.get('reason'), 'time_left', x.meta.get('time_left_s'), 'plan', x.meta.get('plan'),flush=True)
 return x
def obs(seconds=0,depth=True): return record(r.get_obs(seconds=seconds,depth=depth,video='none'),'obs')
def state():
 print('PROPRIO', json.dumps(res.meta['proprio']),flush=True)
def poses(): return np.array(res.group('tcp_pose',now=True)).reshape(2,7)
def q14():
 a=np.array(res.meta['proprio']['now'][:16]); return np.r_[a[:7],a[8:15]]
def move(target, duration=2, dt=.1, label='move'):
 a=np.array(res.meta['proprio']['now'][:16]); arr=np.linspace(a,np.asarray(target),int(round(duration/dt))+1)
 return record(r.submit('joint_position',arr,dt=dt,video='none',depth=True,note=label),label)
def ee(right=None,left=None,grips=None,duration=2,label='ee'):
 p=poses(); dest=p.copy()
 if right is not None: dest[0]=right
 if left is not None: dest[1]=left
 names=['Gripper_Tip_R','Gripper_Tip_L']
 targets={names[i]: dest[i].tolist() for i in range(2) if (right if i==0 else left) is not None}
 ik=r.ik(targets,seed=q14(),max_iters=200)
 print('IK',json.dumps(ik),flush=True)
 if not ik['ok']: return ik
 a=np.array(res.meta['proprio']['now'][:16]); a[:7]=ik['q'][:7]; a[8:15]=ik['q'][7:]
 if grips is not None:
  for i,g in enumerate(grips):
   if g is not None: a[7 if i==0 else 15]=g
 return move(a,duration=duration,label=label)
def quat(mat):
 xyzw=Rot.from_matrix(mat).as_quat(); return np.r_[xyzw[3],xyzw[:3]]
def point(cam,u,v):
 depth=res.last_depth[cam]; K=np.array(res.meta['cameras'][cam]['intrinsic_cv']); E=np.array(res.meta['cameras'][cam]['extrinsic_cv'])
 z=float(depth[int(v),int(u)]); pc=np.linalg.inv(K)@np.array([u,v,1])*z
 return E[:,:3].T@(pc-E[:,3])
obs()
print('READY',flush=True)
if '--replay' in sys.argv:
 lines=(OUT/'commands.jsonl').read_text().splitlines()
else: lines=sys.stdin
for line in lines:
 try:
  cmd=json.loads(line)
  if '--replay' not in sys.argv:
   with (OUT/'commands.jsonl').open('a') as f: f.write(json.dumps(cmd)+'\n')
  print('EXEC',cmd,flush=True)
  exec(cmd,globals())
  print('COMMAND_DONE',flush=True)
 except EpisodeOver as e: print('EPISODE_OVER',str(e),flush=True)
 except Exception: traceback.print_exc()
PY
python -u /app/output/gen.py

